import {
    Table,
    BooleanColumn,
    JsonColumn,
    GenericColumn,
    TranslatedFieldColumn,
    StringColumn,
    ReferenceColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_ux_app_config = Table({
    actions: ['read', 'update', 'delete', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        no_text_index: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'UX App Configuration',
    name: 'sys_ux_app_config',
    schema: {
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        prefetch_limits: JsonColumn({
            label: 'Prefetch Limits',
            maxLength: 8000,
        }),
        encode_query_string: BooleanColumn({
            default: false,
            label: 'Encode Query String',
        }),
        custom_icon: GenericColumn({
            attributes: {
                edge_encryption_enabled: true,
                pdf_cell_type: 'image',
            },
            columnType: 'user_image',
            label: 'Custom Icon',
            maxLength: 255,
        }),
        name: TranslatedFieldColumn({
            label: 'Name',
            mandatory: true,
            maxLength: 255,
        }),
        default_route_type: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Default Route Type',
            maxLength: 255,
        }),
        icon: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Icon',
            referenceTable: 'st_sys_design_system_icon',
        }),
        disable_auto_reflow: BooleanColumn({
            default: false,
            label: 'Disable Auto Reflow',
        }),
        landing_path: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'home',
            label: [
                {
                    hint: 'Landing path is the path of the landing page of the Portal that must be launched on load of the portal',
                    label: 'Landing Path',
                    plural: 'Landing Paths',
                },
            ],
            mandatory: true,
            maxLength: 255,
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 4000,
        }),
        sys_name: StringColumn({}),
        base_url_path: StringColumn({}),
    },
    textIndex: true,
})
